import{_ as a,b as e,c as r,I as o}from"./chunks/framework.C6cPs9Ia.js";const u=JSON.parse('{"title":"周末猫咖探店记：在现实里云吸猫","description":"高中生的周末猫咖探店记录——现实版的云吸猫体验报告","frontmatter":{"title":"周末猫咖探店记：在现实里云吸猫","date":"2026-09-14T00:00:00.000Z","tags":["猫咖","日常","探店"],"cover":"/LQY/images/cover-cafe.webp","head":[["meta",{"name":"description","content":"高中生的周末猫咖探店记录——现实版的云吸猫体验报告"}],["meta",{"name":"keywords","content":"猫咖, 探店, 吸猫, 周末日常"}]]},"headers":[],"relativePath":"posts/ba-diary.md","filePath":"posts/ba-diary.md"}'),d={name:"posts/ba-diary.md"};function i(s,t,l,n,p,h){return e(),r("div",null,[...t[0]||(t[0]=[o('<p>本命是猫娘，现实里又没条件养猫——所以每个月的零花钱预算里，有一项固定支出叫&quot;猫咖基金&quot;。这周末的额度，兑现了。</p><hr><h2 id="门店初印象" tabindex="-1">门店初印象 <a class="header-anchor" href="#门店初印象" aria-label="Permalink to &quot;门店初印象&quot;">​</a></h2><p>这家店藏在学校相反方向的老小区里，要穿过两条梧桐树夹道的巷子。推开门，风铃一响，<strong>七八只猫的视线齐刷刷投过来</strong>，那一刻感觉自己不是顾客，是朝贡的。</p><p>店内装修是原木色 + 猫爬架矩阵，落地窗边的位置最好——阳光斜进来，猫会自己流动到那里，形成一排&quot;晒太阳电池板&quot;。</p><h2 id="猫员工业绩考核" tabindex="-1">猫员工业绩考核 <a class="header-anchor" href="#猫员工业绩考核" aria-label="Permalink to &quot;猫员工业绩考核&quot;">​</a></h2><table tabindex="0"><thead><tr><th>员工</th><th>工种</th><th>业绩评价</th></tr></thead><tbody><tr><td>橘座（橘猫，7kg）</td><td>迎宾</td><td>趴在门口一动不动，用尾巴当门槛，好评</td></tr><tr><td>团子（白猫）</td><td>主力陪玩</td><td>逗猫棒响应速度极快，职业素养满分</td></tr><tr><td>墨汁（黑猫）</td><td>暗杀者</td><td>藏在书架后面偷袭逗猫棒，吓我一跳，扣分（好玩）</td></tr><tr><td>麻薯（三花）</td><td>氛围组</td><td>全程睡觉，但睡姿可爱到犯规，功大于过</td></tr></tbody></table><h2 id="今日高光时刻" tabindex="-1">今日高光时刻 <a class="header-anchor" href="#今日高光时刻" aria-label="Permalink to &quot;今日高光时刻&quot;">​</a></h2><p>给&quot;团子&quot;喂冻干的时候，它吃完没有走，就站在我手边，把脑袋往我掌心里顶了一下。</p><p>就一下。</p><p><strong>整个星期的疲惫全部清零。</strong> 什么函数什么受力分析，那个瞬间全都往后排。</p><p>旁边的小学生问她妈：&quot;哥哥/姐姐为什么在傻笑？&quot;（不透露性别，此处理解为任意一种都行。）</p><p>对不起，不是傻笑，是充电。⚡</p><h2 id="消费小账本" tabindex="-1">消费小账本 <a class="header-anchor" href="#消费小账本" aria-label="Permalink to &quot;消费小账本&quot;">​</a></h2><ul><li>入场券（含一杯饮品）：零花钱的 40%</li><li>冻干一包：15%（猫员工业绩提成）</li><li>猫爪拉花咖啡：好看到下不去嘴，喝了（罪恶感 -1，幸福感 +100）</li></ul><div class="tip custom-block"><p class="custom-block-title">探店结论</p><p>人均消费可控，猫员工业绩感人，回去的公交上满身猫毛——<strong>一个月一次，值回票价。</strong></p></div><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>回家路上在想：雫雫如果是真的猫娘，大概就是团子那个性格——看起来高冷，喂对了冻干就黏人。</p><p>下个月还来。目标：攻略墨汁（黑猫）。以我逗猫棒的技术，应该、大概、可能、行吧。</p><p>（猫咖照片就不放了，拍猫三小时，出片三张，全部糊的。设备问题，不是技术问题，绝对不是。）</p>',20)])])}const b=a(d,[["render",i]]);export{u as __pageData,b as default};
